import { useEffect, useMemo, useRef, useState } from "react";

const STORAGE_KEY = "daylight.tasks.v1";

function makeId() {
  return `t_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function sanitize(parsed) {
  if (!Array.isArray(parsed)) return [];
  return parsed.filter(
    (t) => t && typeof t.id === "string" && typeof t.title === "string"
  );
}

export default function Home() {
  const [tasks, setTasks] = useState([]);
  const [filter, setFilter] = useState("all");
  const [newTitle, setNewTitle] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editValue, setEditValue] = useState("");
  const [hydrated, setHydrated] = useState(false);
  const [storageError, setStorageError] = useState(false);
  const editInputRef = useRef(null);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      const store = window.askkArtifact?.storage;
      let saved = null;
      try {
        if (store) {
          saved = await store.get(STORAGE_KEY);
        } else {
          const raw = window.localStorage.getItem(STORAGE_KEY);
          saved = raw ? JSON.parse(raw) : null;
        }
      } catch {
        saved = null;
      }
      if (!cancelled) {
        setTasks(sanitize(saved));
        setHydrated(true);
      }
    }
    load();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!hydrated) return;
    let cancelled = false;
    async function save() {
      const store = window.askkArtifact?.storage;
      try {
        if (store) {
          await store.set(STORAGE_KEY, tasks);
        } else {
          window.localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
        }
        if (!cancelled) setStorageError(false);
      } catch {
        if (!cancelled) setStorageError(true);
      }
    }
    save();
    return () => {
      cancelled = true;
    };
  }, [tasks, hydrated]);

  useEffect(() => {
    if (editingId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingId]);

  const visibleTasks = useMemo(() => {
    if (filter === "active") return tasks.filter((t) => !t.completed);
    if (filter === "completed") return tasks.filter((t) => t.completed);
    return tasks;
  }, [tasks, filter]);

  const activeCount = useMemo(() => tasks.filter((t) => !t.completed).length, [tasks]);
  const completedCount = useMemo(() => tasks.filter((t) => t.completed).length, [tasks]);

  function addTask(e) {
    e.preventDefault();
    const title = newTitle.trim();
    if (!title) return;
    const task = { id: makeId(), title, completed: false };
    setTasks((prev) => [task, ...prev]);
    setNewTitle("");
  }

  function toggleComplete(id) {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t))
    );
  }

  function deleteTask(id) {
    setTasks((prev) => prev.filter((t) => t.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditValue("");
    }
  }

  function startEdit(task) {
    setEditingId(task.id);
    setEditValue(task.title);
  }

  function cancelEdit() {
    setEditingId(null);
    setEditValue("");
  }

  function commitEdit() {
    const title = editValue.trim();
    if (!title) {
      cancelEdit();
      return;
    }
    setTasks((prev) =>
      prev.map((t) => (t.id === editingId ? { ...t, title } : t))
    );
    setEditingId(null);
    setEditValue("");
  }

  function onEditKeyDown(e) {
    if (e.key === "Enter") {
      e.preventDefault();
      commitEdit();
    } else if (e.key === "Escape") {
      e.preventDefault();
      cancelEdit();
    }
  }

  function clearCompleted() {
    setTasks((prev) => prev.filter((t) => !t.completed));
  }

  return (
    <main className="app">
      <header className="header">
        <div>
          <h1 className="title">Daylight</h1>
