.icon-btn:hover {
  background: var(--surface-2);
  color: var(--text);
}

.empty-state {
  text-align: center;
  padding: 40px 20px;
  color: var(--muted);
  border: 1px dashed var(--border);
  border-radius: 10px;
  background: var(--surface-2);
}

.empty-state h2 {
  margin: 0 0 8px;
  font-size: 18px;
  color: var(--text);
}

.empty-state p {
  margin: 0;
  font-size: 14px;
}

.footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 16px;
  color: var(--muted);
  font-size: 13px;
}

.clear-completed {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 13px;
  cursor: pointer;
  text-decoration: underline;
}

.clear-completed:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.clear-completed:hover {
  color: var(--text);
}

@media (max-width: 520px) {
  .app {
    padding: 20px 14px 48px;
  }

  .header {
    flex-direction: column;
    align-items: flex-start;
  }

  .add-form {
    flex-direction: column;
  }

  .task-item {
    flex-wrap: wrap;
  }

  .task-actions {
    width: 100%;
    justify-content: flex-end;
  }
}
