                    aria-label={`Delete "${task.title}"`}
                  >
                    Delete
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}

        <div className="footer">
          <span>
            {tasks.length} {tasks.length === 1 ? "task" : "tasks"} total
          </span>
          {completedCount > 0 && (
            <button className="clear-completed" onClick={clearCompleted}>
              Clear completed
            </button>
          )}
        </div>
      </section>
    </main>
  );
}
