  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 13px;
  cursor: pointer;
  color: var(--muted);
}

.icon-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.icon-btn:hover {
  background: var(--surface-2);
  color: var(--text);
}

.empty-state {
  text-align: center;
  padding: 40px 20px;
  color: var(--muted);
  border: 1px dashed var(--border);
  border-radius: 10px;
  background: var(--surface-2);
}

.empty-state h2 {
  margin: 0 0 8px;
  font-size: 18px;
